      include_history: { type: 'boolean', description: 'When true, include chronological history.', default: false }
    },
    required: ['order_id'],
    additionalProperties: false
  }
};

export async function listTools() {
  return [ORDER_STATUS_TOOL];
}

export async function callTool(name, args = {}) {
  if (name !== 'order_status') {
    const err = new Error('Unknown tool: ' + name);
    err.code = -32601;
    throw err;
  }

  const error = validateArgs(args);
  if (error) {
    const err = new Error(error);
    err.code = -32602;
    throw err;
  }

  const order = orders[args.order_id];
  if (!order) {
    const err = new Error('Order not found: ' + args.order_id);
    err.code = -32602;
    throw err;
  }

  const includeHistory = args.include_history === true;
  const result = { order_id: args.order_id, status: order.status };
  if (includeHistory) {
    result.history = [...order.history];
  }

  return {
    content: [{ type: 'text', text: JSON.stringify(result) }]
  };
}

function validateArgs(args) {
  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
    return 'Arguments must be an object';
  }
  const allowed = new Set(['order_id', 'include_history']);
  for (const key of Object.keys(args)) {
    if (!allowed.has(key)) {
      return 'Unexpected argument: ' + key;
    }
  }
  if (!('order_id' in args)) {
    return 'Missing required argument: order_id';
  }
  if (typeof args.order_id !== 'string') {
    return 'order_id must be a string';
  }
  if ('include_history' in args && typeof args.include_history !== 'boolean') {
    return 'include_history must be a boolean';
  }
  return null;
}

